{
  "selections": [
    {
      "trait_id": "/core_belief/core_belief_statement",
      "background_ids": ["/childhood_data", "/situations/3"],
      "relevance": "상담사가 '결심하는 순간부터 이미 또 이렇게 되겠지'가 결과가 정해져 있는 것처럼 느껴지는지, 아니면 그렇게 되길 바라는 마음이 섞여 있는지 질문함. 내담자의 핵심 신념 '나는 하기 싫고 답답한 일을 스스로 하게 만들 수 없는 사람이다'가 이 자기실현적 예언의 기저에 있음. 성장 경험에서 '나는 원래 진득하게 못 하는 애'라는 신념이 형성된 과정과, 상황 사례 3에서 '이번이라고 될까'라는 자동 사고가 이 신념이 작동하는 순간을 보여줌."
    },
    {
      "trait_id": "/core_belief/young_schema",
      "background_ids": ["/childhood_data"],
      "relevance": "'또 이렇게 되겠지'라는 선제적 패배 예언은 부족한 자기통제/자기훈련 스키마가 결심 시점에 이미 활성화되어 있음을 시사함. 상담사의 질문이 이 스키마가 고정된 결과인지, 아니면 무의식적 기대인지 구분하려는 것이므로 직접 관련됨. 성장 경험에서 불편함을 피하면 된다는 규칙이 몸에 밴 배경이 이 스키마의 기원."
    },
    {
      "trait_id": "/intermediate_beliefs/assumption_negative",
      "background_ids": ["/situations/3"],
      "relevance": "상담사가 '결과가 정해져 있는 것처럼 느껴지는지' 질문한 것은, 내담자의 부정적 가정(억지로 붙잡고 있어도 집중도 안 되고 괴롭기만 할 뿐)이 결심 시점에 이미 개입되어 '또 이렇게 되겠지'로 수렴하는 과정을 탐색하는 것. 상황 사례 3의 자동 사고 '나는 결심을 지켜본 적이 없는데 이번이라고 될까'가 이 가정의 구체적 표현."
    },
    {
      "trait_id": "/core_belief/young_domain",
      "background_ids": ["/childhood_data"],
      "relevance": "'또 이렇게 되겠지'가 결과가 정해져 있는 것처럼 느껴진다는 것은 손상된 한계 도메인—스스로의 한계가 근본적으로 고정되어 있다는 느낌—과 연결됨. 성장 경험에서 아무도 계속하도록 붙잡지 않은 환경이 이 '고정된 한계' 감각의 형성 배경."
    }
  ]
}

